// Инициализируем переменную для хранения всех найденных ID
const allCustomerIds = [];

// 2. Перебираем каждый входящий элемент и извлекаем ID клиентов.
for (const item of items) {
// Проверяем, существует ли нужная вложенная структура и массив клиентов
// Используем оператор опциональной цепочки ?. для безопасного доступа
const customersArray = item?.json?._embedded?.customers || item?._embedded?.customers;

// Если массив клиентов найден и является массивом, извлекаем ID
if (Array.isArray(customersArray)) {
const idsFromThisItem = customersArray
.map(customer => customer?.id) // Извлекаем id каждого клиента (ожидаем число)
.filter(id => id !== undefined && id !== null); // Убираем null/undefined

// Добавляем найденные ID в общий список
