}
}

// 3. Определяем конкретное число, которое мы хотим проверить на наличие.
// !!! ВАЖНО: ЗАМЕНИ ЧИСЛО 5521 НА НУЖНОЕ ТЕБЕ ЧИСЛО !!!
const specificTargetId = $('Webhook').first().json.body._embedded.threads[0].createdBy.id; // Например, проверяем наличие числа 5521

// 4. Проверяем, содержит ли массив allCustomerIds это конкретное число.
// Используем простой метод .includes().
const foundSpecificId = allCustomerIds.includes(specificTargetId);

// 5. Возвращаем результат в формате, ожидаемом n8n узлом Code (true или false).
// Возвращаем массив с одним объектом, содержащим результат в свойстве 'json'.
