// Получаем текст из Telegram Trigger, если он есть
const telegramText = $('Telegram Trigger').first()?.json?.message?.text;

let openAIContent = null;
try {
  openAIContent = $('OpenAI').first()?.json?.text;
} catch (error) {
  // Обрабатываем случай, когда OpenAI не был выполнен
  if (error.message && (error.message.includes('Referenced node is unexecuted') || error.message.includes("hasn't been executed"))) {
    openAIContent = null;
  } else {
    throw error;
  }
}

// Формируем итоговый текст
let resultText = "";
if (telegramText) {
  resultText = telegramText;
} else if (openAIContent) {
  resultText = `Транскрибация: ${openAIContent}`;
}

// Заменяем переносы строк на ". " и экранируем спецсимволы
const safeText = resultText
  .replace(/[\r\n]+/g, '. ')
  .replace(/\\/g, '\\\\')
  .replace(/"/g, '\\"');

return [
  {
    json: {
      text: safeText,
    },
  },
];

// Берём HTML из Webhook-ноды
const html = $('Webhook').first().json.body._embedded.threads[0].body;

// Находим первый src в теге <img>
const match = html.match(/<img[^>]+src="([^"]+)"/);

// Если нашли - декодируем &amp; и возвращаем полный URL
const imageUrl = match
  ? match[1].replace(/&amp;/g, '&')
  : null;

return [{ json: { imageUrl } }];

