// Берём json первого item'а из узла webhook1
const source = $items('webhook1', 0, 0).json;

// В Webhook тикет лежит в source.body, а в ответе API — в корне.
// Унифицируем:
const convo = source.body ?? source;

// Вытаскиваем threads, оставляя только сообщения и реплики клиента
const threads = (convo._embedded?.threads || [])
  .filter(t => ['customer', 'message'].includes(t.type))
  .sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));

// Утилита: убираем HTML
const stripHtml = s => (s || '')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<[^>]*>/g, '')
  .replace(/&nbsp;/g, ' ')
  .trim();

// Склеиваем диалог
const dialog = threads.map(t => {
  const who = t.type === 'customer' ? 'Пользователь' : 'Поддержка';
  return `${who}: ${stripHtml(t.body)}`;
}).join('\n');

// Отдаём дальше
return [{ json: { dialog } }];

const feedbacks = $input.first().json._embedded.conversations;
return feedbacks.map(feedback => ({
  json: {
    ...feedback, // Копируем все поля feedback
    lastOrderShkId: String(feedback.id) // Преобразуем lastOrderShkId в строку
  }
}));

